import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    def count(seq, ch):
        c = 0
        for x in seq:
            if x == ch:
                c += 1
        return c

    def streak(seq, ch):
        s = 0
        for x in reversed(seq):
            if x == ch:
                s += 1
            else:
                break
        return s

    opp_def = count(opp, 'D')
    my_def = count(my, 'D')
    op_d_streak = streak(opp, 'D')
    last_opp = opp[-1]
    last_my = my[-1]

    # If we defected last but opponent cooperated, they forgave us:
    # immediately return to cooperation to preserve mutual CC.
    if last_opp == 'C' and last_my == 'D' and n >= 2:
        return 'C'

    # Opponent cooperated last round.
    if last_opp == 'C':
        # Mutual cooperation is optimal; only defect strategically vs pure cooperators.
        if opp_def == 0:
            if n < 8:
                return 'C'
            # Exploit a confirmed pure cooperator, but keep enough CC
            # that forgiving opponents recover. Defect with moderate prob.
            if rng.random() < 0.45:
                return 'D'
            return 'C'
        # Exploit mostly-cooperative opponents occasionally, but maintain CC.
        if opp_def <= 1 and n >= 6:
            if rng.random() < 0.08:
                return 'D'
            return 'C'
        # If opponent has history of defecting, occasionally probe.
        if opp_def * 4 < n and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Opponent just defected.
    if op_d_streak >= 4:
        # Sustained defector: defect almost always, rare probe.
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    if op_d_streak >= 2:
        # Two or three consecutive defections. Punish, but do not lock in.
        # Single retaliation then test forgiveness.
        if last_my == 'D':
            # We already retaliated last round; try cooperating to break cycle.
            if rng.random() < 0.55:
                return 'C'
            return 'D'
        return 'D'

    # Single defection. Retaliate once with high probability.
    if last_my == 'D':
        # We already retaliated; return to cooperation to enable recovery.
        return 'C'
    return 'D'
